	case <-ctx.Done():
		t.Fatal(ctx.Err())
	}
	before, err := hosts.ListHosts(ctx)
	if err != nil || len(before) != 1 || !before[0].SessionExpiresAt.IsZero() {
		t.Fatal("unexpected ownhost session before the one Agent", err)
