func managerStartupVault(t *testing.T) (*vault.VaultsClient, *secrets.SecretsClient) {
	t.Helper()
	var mu sync.Mutex
	values := make(map[string]string)
	secretID := func(name string) string {
		sum := sha256.Sum256([]byte(name))
		return "ocid1.vaultsecret.oc1.sa-saopaulo-1." + hex.EncodeToString(sum[:])
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mu.Lock()
		defer mu.Unlock()
		if r.Header.Get("Authorization") == "" {
			http.Error(w, "unsigned Vault SDK request", 401)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		write := func(body any) {
			if err := json.MarshalWrite(w, body); err != nil {
				t.Error(err)
			}
		}
		switch {
		case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/secrets"):
			name := r.URL.Query().Get("name")
			items := []any{}
			if _, ok := values[name]; ok {
				items = append(items, map[string]any{"id": secretID(name), "secretName": name, "lifecycleState": "ACTIVE"})
			}
			write(items)
		case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/secrets"):
			var body struct {
				SecretName    string `json:"secretName"`
				SecretContent struct {
					Content string `json:"content"`
				} `json:"secretContent"`
			}
			if err := json.UnmarshalRead(r.Body, &body); err != nil || body.SecretName == "" || body.SecretContent.Content == "" {
				http.Error(w, "invalid Vault body", 400)
				return
			}
			if _, ok := values[body.SecretName]; ok {
				http.Error(w, `{"code":"Conflict","message":"already exists"}`, 409)
				return
			}
			values[body.SecretName] = body.SecretContent.Content
			write(map[string]any{"id": secretID(body.SecretName), "secretName": body.SecretName, "lifecycleState": "ACTIVE"})
		case r.Method == http.MethodPost && strings.Contains(r.URL.Path, "getByName"):
			name := r.URL.Query().Get("secretName")
			value, ok := values[name]
			if !ok {
				http.Error(w, `{"code":"NotFound","message":"absent"}`, 404)
				return
			}
			write(map[string]any{"secretId": secretID(name), "versionNumber": 1, "secretBundleContent": map[string]string{"contentType": "BASE64", "content": value}})
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/secretbundles/"):
			for name, value := range values {
				if strings.HasSuffix(r.URL.Path, "/"+secretID(name)) && r.URL.Query().Get("versionNumber") == "1" {
					write(map[string]any{"secretId": secretID(name), "versionNumber": 1, "secretBundleContent": map[string]string{"contentType": "BASE64", "content": value}})
					return
				}
			}
			http.Error(w, `{"code":"NotFound","message":"absent version"}`, 404)
		default:
			http.Error(w, "unexpected Vault SDK operation", 404)
		}
	}))
	t.Cleanup(server.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	private := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..test", "ocid1.user.oc1..test", "sa-saopaulo-1", "fixture-fingerprint", string(private), nil)
	management, err := vault.NewVaultsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	read, err := secrets.NewSecretsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	management.Host, management.HTTPClient = server.URL, server.Client()
	read.Host, read.HTTPClient = server.URL, server.Client()
	return &management, &read
}

func StartAcceptedNodeFixture(ctx context.Context, stateDir string,
	reader *bootstrapstart.CurrentFounderAuthorityReader, accepted bootstrapstart.AcceptedIdentity,
	foundations region.FoundationResolver, vault vaultsecret.VaultClient, bundles vaultsecret.BundleClient,
	executor exec.Executor, observer *bootstrapstart.OCIInstanceObserver, hostEnrollment []byte,
) (*Node, error) {
	if !filepath.IsAbs(stateDir) || filepath.Clean(stateDir) != stateDir || stateDir == "/" || observer == nil || vault == nil || bundles == nil {
		return nil, errors.New("accepted manager fixture requires an isolated directory and concrete OCI clients")
	}
	authority, err := reader.ReadRuntimeAuthority(ctx, accepted, time.Now().UTC())
	if err != nil {
		return nil, err
	}
	identity := authority.Identity()
	foundation, err := foundations.Resolve(ctx, strings.ToUpper(identity.Cell))
	if err != nil {
		return nil, err
	}
	if foundation.OCIRegion != authority.Anchor().Anchor().OCIRegion {
		return nil, errors.New("fixture foundation differs from signed regional authority")
	}
	target, err := foundation.VaultTarget()
	if err != nil {
		return nil, err
	}
	digest := sha256.Sum256(hostEnrollment)
	if hex.EncodeToString(digest[:]) != accepted.LaunchMaterialSHA256[bootstrapstart.HostEnrollmentFilename] {
		return nil, errors.New("fixture enrollment differs from accepted launch pin")
	}
	bundle, err := hostenroll.ParsePublicBundle(hostEnrollment)
	if err != nil {
		return nil, err
	}
	if bundle.MatchesImageLayout() != nil || bundle.Cell != strings.ToLower(identity.Cell) || bundle.Region != identity.Cell || bundle.Environment != identity.Environment {
		return nil, errors.New("fixture enrollment differs from signed runtime scope")
	}
	public, err := bundle.ResponsePublicKey()
	if err != nil {
		return nil, err
	}
	refresh := func(ctx context.Context) error {
		current, err := reader.ReadRuntimeAuthority(ctx, accepted, time.Now().UTC())
		if err != nil {
			return err
		}
		if current.Identity() != identity {
			return errors.New("fixture runtime authority changed")
		}
		fresh, err := foundations.Resolve(ctx, strings.ToUpper(identity.Cell))
		if err != nil {
			return err
		}
		freshTarget, err := fresh.VaultTarget()
		if err != nil {
			return err
		}
		if fresh.OCIRegion != foundation.OCIRegion || freshTarget != target {
			return errors.New("fixture regional Vault foundation changed")
		}
		return nil
	}
	n, err := startAcceptedNodeAt(ctx, stateDir, identity, target, vault, bundles, executor, refresh)
	if err != nil {
		return nil, err
	}
	n.workerAuthority = &workerAuthority{identity: identity, public: public, target: target, vault: vault, bundles: bundles, observer: observer, refresh: refresh}
	return n, nil
}

func startAcceptedNodeAt(ctx context.Context, stateDir string, identity bootstrapstart.RuntimeIdentity,
	target vaultsecret.Target, vault vaultsecret.VaultClient, bundles vaultsecret.BundleClient,
	executor exec.Executor, refresh func(context.Context) error,
) (*Node, error) {
	if err := refresh(ctx); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(stateDir, 0o700); err != nil {
		return nil, err
	}
	lock := flock.New(filepath.Join(stateDir, "bootstrap.lock"))
	locked, err := lock.TryLock()
	if err != nil || !locked {
		return nil, errors.New("SwarmKit bootstrap state is already in use")
	}
	defer lock.Unlock()
	if err := bindBootstrapScope(stateDir, identity); err != nil {
		return nil, err
	}
	scope := bootstrapScope{DeploymentID: identity.DeploymentID, ClusterID: identity.ClusterID,
		Environment: identity.Environment, Cell: identity.Cell, OCIRegion: identity.OCIRegion, SeedSlot: identity.SeedSlot}
	name := vaultsecret.Name(strings.ToLower(identity.Cell)+"-"+strings.ToLower(identity.ClusterID), "TS_ORCHESTRATOR_SWARM_JOIN")
	wire, readErr := vaultsecret.Read(ctx, bundles, target.VaultID, name)
	var published bootstrapJoinMaterial
	if readErr == nil {
		if err := json.Unmarshal([]byte(wire), &published, json.RejectUnknownMembers(true)); err != nil ||
			published.Version != 1 || published.Scope != scope || published.SwarmID == "" || published.CAPEM == "" ||
			published.ManagerAddress != net.JoinHostPort(identity.SeedPrivateIP, swarmManagerPort) {
			return nil, errors.New("Vault SwarmKit join material differs from signed regional scope")
		}
		for _, token := range []string{published.ManagerToken, published.WorkerToken} {
			if _, err := ca.ParseJoinToken(token); err != nil {
				return nil, errors.New("Vault SwarmKit join material has an invalid upstream token")
			}
		}
	} else if !vaultsecret.Absent(readErr) {
		return nil, readErr
	}
	admission := managerAdmission(identity)
	nodeDir := filepath.Join(stateDir, "node")
	if identity.Slot == identity.SeedSlot {
		if readErr == nil {
			if _, err := os.Stat(filepath.Join(nodeDir, "certificates", "swarm-node.crt")); err != nil {
				return nil, errors.New("regional SwarmKit cluster already exists; restore founder state")
			}
		}
	} else {
		if readErr != nil {
			return nil, errors.New("regional SwarmKit founder has not published join material")
		}
		admission.ManagerAddress, admission.JoinToken = published.ManagerAddress, published.ManagerToken
	}
	if err := refresh(ctx); err != nil {
		return nil, err
	}
	n, err := StartNode(ctx, NodeConfig{StateDir: nodeDir,
		ListenAddress:    net.JoinHostPort(identity.PrivateIP, swarmManagerPort),
		AdvertiseAddress: net.JoinHostPort(identity.PrivateIP, swarmManagerPort), Admission: admission}, executor)
	if err != nil {
		return nil, err
	}
	var startupErr error
	defer func() {
		if startupErr != nil {
			stopCtx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
			defer cancel()
			_ = n.Stop(stopCtx)
		}
	}()
	client, err := n.ControlClient(ctx)
	if err != nil {
		startupErr = err
		return nil, err
	}
	clusters, err := client.ListClusters(ctx, &api.ListClustersRequest{})
	if err != nil || len(clusters.Clusters) != 1 {
		startupErr = errors.New("SwarmKit did not expose one regional cluster")
		return nil, startupErr
	}
	cluster := clusters.Clusters[0]
	actual := bootstrapJoinMaterial{Version: 1, Scope: scope,
		ManagerAddress: net.JoinHostPort(identity.SeedPrivateIP, swarmManagerPort),
		SwarmID:        cluster.ID, CAPEM: string(cluster.RootCA.CACert),
		ManagerToken: cluster.RootCA.JoinTokens.Manager, WorkerToken: cluster.RootCA.JoinTokens.Worker}
	if readErr == nil && published != actual {
		startupErr = errors.New("running SwarmKit cluster differs from create-once Vault material; restore its matching state")
		return nil, startupErr
	}
	if err := refresh(ctx); err != nil {
		startupErr = err
		return nil, err
	}
	if identity.Slot == identity.SeedSlot {
		stored, err := vaultsecret.Ensure(ctx, vault, target, name, "Regional SwarmKit upstream join material", func(ctx context.Context) (string, error) {
			if err := refresh(ctx); err != nil {
				return "", err
			}
			data, err := json.Marshal(actual)
			return string(data), err
		})
		if err != nil {
			startupErr = err
			return nil, err
		}
		readback, err := vaultsecret.ReadBack(ctx, bundles, target.VaultID, name, stored.Created || stored.Provisioning)
		var saved bootstrapJoinMaterial
		if err != nil || json.Unmarshal([]byte(readback), &saved, json.RejectUnknownMembers(true)) != nil || saved != actual {
			startupErr = errors.New("Vault SwarmKit create-once readback differs from running cluster")
			return nil, startupErr
		}
	}
	if err := refresh(ctx); err != nil {
		startupErr = err
		return nil, err
	}
	if _, err := AdmitNode(ctx, client, n.ID(), admission); err != nil {
		startupErr = err
		return nil, err
	}
	return n, nil
}

func (source *managedRuntimeHost) CurrentContainerMaterial(ctx context.Context, binding swarmruntime.ContainerTaskBinding) (result swarmruntime.ContainerMaterial, resultErr error) {
	source.mu.RLock()
	defer source.mu.RUnlock()
	if source.agent == nil || source.session == nil || source.session.Err() != nil {
		return result, errors.New("controller container material awaits its current ownhost session")
	}
	ctx, cancel := context.WithCancel(ctx)
	stop := context.AfterFunc(source.session, cancel)
	defer func() { stop(); cancel() }()
	current, err := swarmruntime.ReadControllerHostBinding(ctx, source.reader, source.accepted, source.agent, source.transport.Request, source.transport.Response)
	if err != nil {
		return result, err
	}
	identity := current.Identity()
	if binding.NodeID != source.nodeID || binding.HostID != current.ControllerSlot() || binding.InstanceID != identity.InstanceID || binding.Region != identity.OCIRegion {
		return result, errors.New("controller material differs from its accepted manager slot")
	}
	transportBinding := binding
	transportBinding.HostID = current.HostID()
	result, err = (containerMaterialSource{agent: source.agent}).CurrentContainerMaterial(ctx, transportBinding)
	if err != nil {
		return result, err
	}
	defer func() {
		if resultErr != nil {
			for _, value := range result.Files {
				clear(value)
			}
			result = swarmruntime.ContainerMaterial{}
		}
	}()
	if ctx.Err() != nil || source.session.Err() != nil || !time.Now().Before(result.ExpiresAt) {
		return result, errors.New("controller ownhost changed during material delivery")
	}
	result.Binding = binding
	return result, nil
}

func (source *managedRuntimeHost) registryResolver(ctx context.Context, task *api.Task, node *api.Node) (remotes.Resolver, error) {
	source.mu.RLock()
	defer source.mu.RUnlock()
	if source.agent == nil || source.registry == nil || source.session == nil || source.session.Err() != nil {
		return nil, errors.New("controller registry awaits its current ownhost session")
	}
	ctx, cancel := context.WithCancel(ctx)
	stop := context.AfterFunc(source.session, cancel)
	defer func() { stop(); cancel() }()
	resolver, err := source.registry(ctx, task, node)
	if err != nil {
		return nil, err
	}
	if ctx.Err() != nil || source.session.Err() != nil {
		return nil, errors.New("controller ownhost session ended during registry admission")
	}
	return resolver, nil
}

func StartNode(ctx context.Context, cfg NodeConfig, executor exec.Executor) (*Node, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	a := cfg.Admission
	if cfg.StateDir == "" || a.Region == "" || a.HostID == "" || a.InstanceID == "" || a.FounderID == "" || executor == nil {
		return nil, errors.New("swarm node requires persistent state, admitted identity and executor")
	}
	if a.Role != "manager" && a.Role != "container" && a.Role != "wasm" {
		return nil, errors.New("swarm node requires an admitted manager, container or wasm host role")
	}
	if a.HostID == a.FounderID && (a.Role != "manager" || a.ManagerAddress != "" || a.JoinToken != "") {
		return nil, errors.New("regional founder admission must be a manager without join material")
	}
	for _, address := range []string{cfg.ListenAddress, cfg.AdvertiseAddress} {
		if _, _, err := net.SplitHostPort(address); err != nil {
			return nil, fmt.Errorf("invalid swarm address: %w", err)
		}
	}
	if err := os.MkdirAll(cfg.StateDir, 0o700); err != nil {
		return nil, err
	}
	lock := flock.New(filepath.Join(cfg.StateDir, "node.lock"))
	locked, err := lock.TryLock()
	if err != nil {
		return nil, err
	}
	if !locked {
		return nil, errors.New("swarm node state is already in use")
	}
	var n *Node
	defer func() {
		if n == nil {
			_ = lock.Unlock()
		}
	}()

	identity := admittedIdentity{Region: a.Region, HostID: a.HostID, InstanceID: a.InstanceID, FounderID: a.FounderID, Role: a.Role}
	admissionPath := filepath.Join(cfg.StateDir, "admission.json")
	stored, err := os.ReadFile(admissionPath)
	existingAdmission := err == nil
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	if existingAdmission {
		var previous admittedIdentity
		if err := json.Unmarshal(stored, &previous); err != nil {
			return nil, fmt.Errorf("read swarm admission: %w", err)
		}
		if previous != identity {
			return nil, errors.New("swarm admission cannot change an existing node identity or role")
		}
	}

	paths := ca.NewConfigPaths(filepath.Join(cfg.StateDir, "certificates"))
	hasIdentity := true
	for _, path := range []string{paths.RootCA.Cert, paths.Node.Cert, paths.Node.Key} {
		info, err := os.Stat(path)
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			return nil, err
		}
		if err != nil || !info.Mode().IsRegular() || info.Size() == 0 {
			hasIdentity = false
		}
	}
	joinAddress, joinToken := "", ""
	if !hasIdentity {
		if a.HostID == a.FounderID {
			// A failed/partial founder initialization requires explicit recovery;
			// a missing certificate must never silently create a second cluster.
			if existingAdmission {
				return nil, errors.New("regional founder identity is missing; restore its persistent state")
			}
			entries, err := os.ReadDir(cfg.StateDir)
			if err != nil {
				return nil, err
			}
			for _, entry := range entries {
				if entry.Name() != "node.lock" {
					return nil, errors.New("regional founder requires empty initial state or complete persisted identity")
				}
			}
		} else {
			if _, _, err := net.SplitHostPort(a.ManagerAddress); err != nil {
				return nil, errors.New("joining node requires an admitted manager address")
			}
			if _, err := ca.ParseJoinToken(a.JoinToken); err != nil {
				return nil, errors.New("joining node requires a valid Vault-delivered SwarmKit join token")
			}
			joinAddress, joinToken = a.ManagerAddress, a.JoinToken
		}
	}
	if hasIdentity && a.Role == "manager" {
		entries, err := os.ReadDir(filepath.Join(cfg.StateDir, "raft"))
		if err != nil || len(entries) == 0 {
			return nil, errors.New("manager Raft state is missing; restore its persistent state")
		}
	}
	if !existingAdmission {
		data, err := json.Marshal(identity)
		if err != nil {
			return nil, err
		}
		file, err := os.OpenFile(admissionPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if err != nil {
			return nil, err
		}
		_, writeErr := file.Write(data)
		if err := errors.Join(writeErr, file.Sync(), file.Close()); err != nil {
			return nil, err
		}
	}
	if hasIdentity || joinAddress != "" {
		rootCA, err := ca.GetLocalRootCA(paths.RootCA)
		peers := remotes.NewRemotes()
		if joinAddress != "" {
			peers.Observe(api.Peer{Addr: joinAddress}, remotes.DefaultObservationWeight)
		}
		broker := connectionbroker.New(peers)
		if errors.Is(err, ca.ErrNoLocalRootCA) && joinAddress != "" {
			rootCA, err = ca.DownloadRootCA(ctx, paths.RootCA, joinToken, broker)
		}
		if err != nil {
			return nil, err
		}
		keys := ca.NewKeyReadWriter(paths.Node, nil, &manager.RaftDEKData{})
		var security *ca.SecurityConfig
		var cleanup func() error
		if hasIdentity {
			security, cleanup, err = ca.LoadSecurityConfig(ctx, rootCA, keys, false)
		} else {
			security, cleanup, err = rootCA.CreateSecurityConfig(ctx, keys, ca.CertificateRequestConfig{Token: joinToken, ConnBroker: broker})
		}
		if err != nil {
			return nil, err
		}
		role := security.ClientTLSCreds.Role()
		if err := cleanup(); err != nil {
			return nil, err
		}
		if (role == ca.ManagerRole) != (a.Role == "manager") {
			err := errors.New("SwarmKit certificate role does not match admitted host role")
			if !hasIdentity {
				err = errors.Join(err, os.Remove(paths.Node.Cert), os.Remove(paths.Node.Key))
			}
			return nil, err
		}
	}
	upstream, err := swarmnode.New(&swarmnode.Config{
		Hostname:           a.HostID,
		StateDir:           cfg.StateDir,
		JoinAddr:           joinAddress,
		JoinToken:          joinToken,
		ListenControlAPI:   filepath.Join(cfg.StateDir, "control.sock"),
		ListenRemoteAPI:    cfg.ListenAddress,
		AdvertiseRemoteAPI: cfg.AdvertiseAddress,
		Executor:           executor,
	})
	if err != nil {
		return nil, err
	}
	runCtx, cancel := context.WithCancel(ctx)
	if err := upstream.Start(runCtx); err != nil {
		cancel()
		return nil, err
	}
	n = &Node{upstream: upstream, cancel: cancel, done: make(chan struct{}), role: a.Role, admission: identity, stateDir: cfg.StateDir}
	go func() {
		n.err = errors.Join(upstream.Err(context.Background()), lock.Unlock())
		close(n.done)
	}()
	select {
	case <-upstream.Ready():
		if (upstream.Manager() != nil) == (a.Role == "manager") {
			return n, nil
		}
		err = errors.New("SwarmKit certificate role does not match admitted host role")
	case <-n.done:
		err = n.err
		if err == nil {
			err = errors.New("swarm node stopped before registration")
		}
	case <-ctx.Done():
		err = ctx.Err()
	}
	stopCtx, stopCancel := context.WithTimeout(context.Background(), 15*time.Second)
	defer stopCancel()
	return nil, errors.Join(err, n.Stop(stopCtx))
}

func (n *Node) ControlClient(ctx context.Context) (api.ControlClient, error) {
	if n.role != "manager" || n.upstream.Manager() == nil {
		return nil, errors.New("swarm control API requires an admitted manager")
	}
	waitCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	for conn := range n.upstream.ListenControlSocket(waitCtx) {
		if conn != nil {
			return api.NewControlClient(conn), nil
		}
	}
	return nil, ctx.Err()
}

